const readline = require('readline');

const rl = readline.createInterface({
    input: process.stdin,
    terminal: false
});

let lines = [];
rl.on('line', (line) => {
    lines.push(line);
    if (lines.length === 2) {
        rl.close();
        process();
    }
});

function process() {
    const s = lines[0].trim();
    const t = lines[1].trim();

    let shours = parseInt(s.substring(0, 2), 10);
    let thours = parseInt(t.substring(0, 2), 10);

    let smins = parseInt(s.substring(3), 10);
    let tmins = parseInt(t.substring(3), 10);

    let answerhours = shours - thours;
    if (answerhours < 0) {
        answerhours += 24;
    }

    let answermins = smins - tmins;
    if (answermins < 0) {
        answermins += 60;
        answerhours--;
        if (answerhours < 0) {
            answerhours = 23;
        }
    }

    let stringhours = answerhours.toString();
    let stringmins = answermins.toString();

    if (stringhours.length === 1) {
        stringhours = "0" + stringhours;
    }
    if (stringmins.length === 1) {
        stringmins = "0" + stringmins;
    }

    console.log(stringhours + ":" + stringmins);
}
